  <script>
    const attendanceOptions = document.querySelectorAll('input[name="attending"]');
    const guests = document.querySelector('#guests');
    const syncGuests = () => {
      const isAttending = document.querySelector('input[name="attending"]:checked')?.value === '1';
      guests.readOnly = !isAttending;
      if (!isAttending) guests.value = 0;
    };
    attendanceOptions.forEach(option => option.addEventListener('change', syncGuests));
    syncGuests();

    const targetDate = new Date('2026-08-29T14:00:00-06:00').getTime();
    const countdownFields = {
      days: document.querySelector('#days'), hours: document.querySelector('#hours'),
      minutes: document.querySelector('#minutes'), seconds: document.querySelector('#seconds')
    };
    const updateCountdown = () => {
      const remaining = Math.max(0, targetDate - Date.now());
      countdownFields.days.textContent = String(Math.floor(remaining / 86400000)).padStart(2, '0');
      countdownFields.hours.textContent = String(Math.floor(remaining / 3600000) % 24).padStart(2, '0');
      countdownFields.minutes.textContent = String(Math.floor(remaining / 60000) % 60).padStart(2, '0');
      countdownFields.seconds.textContent = String(Math.floor(remaining / 1000) % 60).padStart(2, '0');
      if (remaining === 0) document.querySelector('.hud-label').textContent = 'SISTEMA STARK · ¡LA MISIÓN HA COMENZADO!';
    };
    updateCountdown();
    setInterval(updateCountdown, 1000);

    const music = document.querySelector('#ambientMusic');
    const musicToggle = document.querySelector('#musicToggle');
    musicToggle.addEventListener('click', async () => {
      if (music.paused) {
        try {
          music.muted = false;
          music.volume = 1;
          await music.play();
          musicToggle.setAttribute('aria-pressed', 'true');
          musicToggle.setAttribute('aria-label', 'Pausar música');
          musicToggle.title = 'Pausar música';
          document.querySelector('#musicIcon').textContent = '♫';
          document.querySelector('#musicLabel').textContent = 'PAUSAR MÚSICA';
        } catch (error) {
          document.querySelector('#musicLabel').textContent = 'AUDIO NO DISPONIBLE';
        }
      } else {
        music.pause();
        musicToggle.setAttribute('aria-pressed', 'false');
        musicToggle.setAttribute('aria-label', 'Activar música');
        musicToggle.title = 'Activar música';
        document.querySelector('#musicIcon').textContent = '♪';
        document.querySelector('#musicLabel').textContent = 'ACTIVAR MÚSICA';
      }
    });

    document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => {
      document.querySelector('#' + button.dataset.close).classList.remove('show');
    }));

    const rescueOverlay = document.querySelector('#rescueOverlay');
    const gameArena = document.querySelector('#gameArena');
    const pozoleTarget = document.querySelector('#pozoleTarget');
    const greenGoblin = document.querySelector('#greenGoblin');
    const gameScore = document.querySelector('#gameScore');
    const gameTime = document.querySelector('#gameTime');
    const gameStatus = document.querySelector('#gameStatus');
    const startGameButton = document.querySelector('#startGame');
    let rescueScore = 0;
    let rescueSeconds = 12;
    let rescueInterval;
    let goblinInterval;
    let rescueRunning = false;
    const movePozole = () => {
      const padding = 10;
      const maxX = Math.max(padding, gameArena.clientWidth - pozoleTarget.offsetWidth - padding);
      const maxY = Math.max(padding, gameArena.clientHeight - pozoleTarget.offsetHeight - padding);
      pozoleTarget.style.left = padding + Math.random() * (maxX - padding) + 'px';
      pozoleTarget.style.top = padding + Math.random() * (maxY - padding) + 'px';
    };
    const moveGoblin = () => {
      const maxX = Math.max(8, gameArena.clientWidth - greenGoblin.offsetWidth - 8);
      const maxY = Math.max(8, gameArena.clientHeight - greenGoblin.offsetHeight - 8);
      greenGoblin.style.left = Math.random() * maxX + 'px';
      greenGoblin.style.top = Math.random() * maxY + 'px';
    };
    const finishRescue = won => {
      rescueRunning = false;
      clearInterval(rescueInterval);
      clearInterval(goblinInterval);
      pozoleTarget.classList.remove('active');
      startGameButton.textContent = 'JUGAR DE NUEVO';
      gameStatus.textContent = won ? '¡POZOLE A SALVO! La fiesta puede continuar.' : 'El Duende escapó con el pozole… ¡inténtalo otra vez!';
      if (won) {
        for (let i = 0; i < 18; i++) {
          const piece = document.createElement('span');
          piece.className = 'web-confetti';
          piece.textContent = i % 2 ? '🕸' : '✦';
          piece.style.left = Math.random() * 100 + 'vw';
          piece.style.setProperty('--drift', (Math.random() * 140 - 70) + 'px');
          rescueOverlay.appendChild(piece);
          setTimeout(() => piece.remove(), 3200);
        }
        navigator.vibrate?.([70, 40, 70]);
      }
    };
    const startRescue = () => {
      clearInterval(rescueInterval);
      clearInterval(goblinInterval);
      rescueScore = 0;
      rescueSeconds = 12;
      rescueRunning = true;
      gameScore.textContent = '0/7';
      gameTime.textContent = '12';
      gameStatus.textContent = '¡Rápido! Toca el pozole.';
      startGameButton.textContent = 'REINICIAR';
      pozoleTarget.classList.add('active');
      requestAnimationFrame(movePozole);
      moveGoblin();
      goblinInterval = setInterval(moveGoblin, 760);
      rescueInterval = setInterval(() => {
        rescueSeconds--;
        gameTime.textContent = rescueSeconds;
        if (rescueSeconds <= 0) finishRescue(false);
      }, 1000);
    };
    document.querySelector('#openRescue').addEventListener('click', () => rescueOverlay.classList.add('show'));
    startGameButton.addEventListener('click', startRescue);
    pozoleTarget.addEventListener('click', () => {
      if (!rescueRunning) return;
      rescueScore++;
      gameScore.textContent = rescueScore + '/7';
      gameArena.classList.remove('web-hit');
      void gameArena.offsetWidth;
      gameArena.classList.add('web-hit');
      const impact = document.createElement('span');
      impact.className = 'web-impact';
      impact.style.left = (pozoleTarget.offsetLeft + pozoleTarget.offsetWidth / 2 - 9) + 'px';
      impact.style.top = (pozoleTarget.offsetTop + pozoleTarget.offsetHeight / 2 - 9) + 'px';
      gameArena.appendChild(impact);
      setTimeout(() => impact.remove(), 500);
      if (rescueScore >= 7) finishRescue(true);
      else {
        movePozole();
        moveGoblin();
      }
    });
    document.querySelector('[data-close="rescueOverlay"]').addEventListener('click', () => {
      clearInterval(rescueInterval);
      clearInterval(goblinInterval);
      rescueRunning = false;
      pozoleTarget.classList.remove('active');
    });

    const successOverlay = document.querySelector('#successOverlay');
    if (successOverlay.classList.contains('show')) {
      for (let i = 0; i < 32; i++) {
        const piece = document.createElement('span');
        piece.className = 'web-confetti';
        piece.textContent = i % 3 === 0 ? '🕸' : '✦';
        piece.style.left = Math.random() * 100 + 'vw';
        piece.style.setProperty('--drift', (Math.random() * 180 - 90) + 'px');
        piece.style.animationDelay = Math.random() * .8 + 's';
        successOverlay.appendChild(piece);
        setTimeout(() => piece.remove(), 3800);
      }
    }

    const secretTarget = document.querySelector('#secretTarget');
    let secretClicks = 0;
    let secretTimer;
    secretTarget.addEventListener('click', event => {
      event.preventDefault();
      secretClicks++;
      clearTimeout(secretTimer);
      if (secretClicks >= 5) {
        secretClicks = 0;
        document.querySelector('#secretOverlay').classList.add('show');
        return;
      }
      secretTimer = setTimeout(() => {
        window.location.href = secretTarget.href;
      }, 700);
    });

    const symbioteTrigger = document.querySelector('#symbioteTrigger');
    const symbioteToast = document.querySelector('#symbioteToast');
    let symbioteTimer;
    let symbioteActivated = false;
    const stopSymbioteCharge = () => {
      clearTimeout(symbioteTimer);
      symbioteTrigger.classList.remove('charging');
    };
    const startSymbioteCharge = event => {
      event.preventDefault();
      stopSymbioteCharge();
      symbioteActivated = false;
      symbioteTrigger.classList.add('charging');
      symbioteTimer = setTimeout(() => {
        symbioteActivated = true;
        document.body.classList.toggle('symbiote');
        const active = document.body.classList.contains('symbiote');
        symbioteToast.textContent = active ? 'SIMBIONTE DETECTADO · MODO NEGRO ACTIVADO' : 'SIMBIONTE RETIRADO · SISTEMA RESTAURADO';
        symbioteToast.classList.add('show');
        navigator.vibrate?.([80, 40, 120]);
        setTimeout(() => symbioteToast.classList.remove('show'), 2600);
        stopSymbioteCharge();
      }, 3000);
    };
    symbioteTrigger.addEventListener('pointerdown', startSymbioteCharge);
    ['pointerup', 'pointercancel', 'pointerleave'].forEach(type => symbioteTrigger.addEventListener(type, stopSymbioteCharge));
    symbioteTrigger.addEventListener('contextmenu', event => event.preventDefault());
  </script>
</body>
</html>
